css:
.v-title{writing-mode:vertical-rl; font-feature-settings:'palt' 1; letter-spacing:.16em; line-height:2.4; font-size:clamp(20px,2.4vw,28px)}
.v-label{writing-mode:vertical-rl; text-orientation:sideways; font-size:9px; letter-spacing:.32em; color:#8b2331; margin-left:2px}
/* 和文を正立で積む場合 */
.v-label.ja{text-orientation:upright; letter-spacing:.25em}
/* 原稿用紙の柱にする */
.v-title span{display:inline-block; border-left:1px dotted #c0c0c0; padding-inline:16px}
.rail{display:flex; flex-direction:row-reverse; gap:14px; align-items:flex-start}
